for each word: mask = bits of its letters; register mask → index in map (if mask already present, union the two words)
for each word i:
  for each set bit b:
    sub = mask without b
    if sub in map: union(i, that word)
    for each unset bit c:
      if (sub with c) in map: union(i, that word)
answer = [number of components, largest component size]

code.cpp:
class Solution {
    vector<int> par, sz;
    int groups, best;

    int find(int x) {
        while (par[x] != x) {
            par[x] = par[par[x]];
            x = par[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        par[b] = a;
        sz[a] += sz[b];
        groups--;
        best = max(best, sz[a]);
    }

public:
    vector<int> groupStrings(vector<string>& words) {
        int n = words.size();
        par.resize(n);
        sz.assign(n, 1);
        groups = n;
        best = 1;
        unordered_map<int, int> id;
        id.reserve(2 * n);
        vector<int> masks(n);
        for (int i = 0; i < n; i++) {
            int m = 0;
            for (char c : words[i]) m |= 1 << (c - 'a');
            masks[i] = m;
            auto it = id.find(m);
            if (it == id.end()) id[m] = i;
            else unite(i, it->second);
            par[i] = i;
        }
        for (int i = 0; i < n; i++) {
            int m = masks[i];
            for (int b = 0; b < 26; b++) {
                if (m >> b & 1) {
                    int sub = m ^ (1 << b);
                    auto it = id.find(sub);
                    if (it != id.end()) unite(i, it->second);
                    for (int c = 0; c < 26; c++) {
                        if (!(m >> c & 1)) {
                            auto it2 = id.find(sub | (1 << c));
                            if (it2 != id.end()) unite(i, it2->second);
                        }
                    }
                }
            }
        }
        return {groups, best};
    }
};
